use xiom.io;
use xiom.iter;

fn main() {
  let days: Vec[Str] = ["Mon", "Tue", "Wed", "Thu", "Fri"];
  for __i in range(0, days.len()) {
    let day = days[__i];
    io.print("Today is ");
    io.println(day);
  }
}
